begin;
select plan(18);
insert into auth.users(id,instance_id,aud,role,email,created_at,updated_at) values
('00000000-0000-4000-8000-00000000f001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','setup-editor@example.invalid',now(),now()),
('00000000-0000-4000-8000-00000000f002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','setup-outsider@example.invalid',now(),now());
insert into public.workspaces(id,name,created_by) values ('00000000-0000-4000-8000-00000000f010','Setup contract','00000000-0000-4000-8000-00000000f001');
insert into public.workspace_memberships(workspace_id,user_id,technical_role,status) values ('00000000-0000-4000-8000-00000000f010','00000000-0000-4000-8000-00000000f001','owner','active');
insert into public.project_states(id,workspace_id,name,stage,commercial_stage,status,priority,created_by,owner_user_id) values ('00000000-0000-4000-8000-00000000f020','00000000-0000-4000-8000-00000000f010','Setup fixture','project_authorization_setup','project_authorization_setup','active','medium','00000000-0000-4000-8000-00000000f001','00000000-0000-4000-8000-00000000f001');
insert into public.authorization_records(id,project_state_id,outcome,actor_user_id) values ('00000000-0000-4000-8000-00000000f030','00000000-0000-4000-8000-00000000f020','approved','00000000-0000-4000-8000-00000000f001');

select set_config('test.contract_data','{"partyIds":[],"agreementRevisionId":"","agreementEvidenceId":"","compensationModel":"fee","contractValue":"","currency":"","feeBasis":"Monthly management fee","paymentTerms":"Monthly invoice","reviewDecisionId":"","riskAssessment":"","riskIds":[],"effectiveFrom":"","effectiveUntil":""}',true);
insert into public.user_permission_overrides(workspace_id,user_id,permission_key,effect) values ('00000000-0000-4000-8000-00000000f010','00000000-0000-4000-8000-00000000f001','project.setup.edit','grant');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-00000000f001","role":"authenticated"}',true);
select throws_ok($$select public.request_project_contract_review('00000000-0000-4000-8000-00000000f020',0,'00000000-0000-4000-8000-00000000f060')$$,'P0001','save_contract_before_request','unsaved preparation cannot be requested');
select public.save_project_contract('00000000-0000-4000-8000-00000000f020',0,'00000000-0000-4000-8000-00000000f040',current_setting('test.contract_data')::jsonb);
select is(public.request_project_contract_review('00000000-0000-4000-8000-00000000f020',1,'00000000-0000-4000-8000-00000000f060')->>'submittedVersion','1','nonbinding review may identify incomplete preparation');
select is(public.request_project_contract_review('00000000-0000-4000-8000-00000000f020',1,'00000000-0000-4000-8000-00000000f060')->>'submittedVersion','1','lost response recovers same request');
select is((select count(*)::integer from public.project_contract_review_requests),1,'retry produces exactly one request');
select is(public.read_project_contract('00000000-0000-4000-8000-00000000f020')->'reviewRequests'->0->>'status','pending','reopen exposes pending request');
select is(public.read_project_contract('00000000-0000-4000-8000-00000000f020')->>'approvalVerified','false','review request never approves');
select throws_ok($$select public.request_project_contract_review('00000000-0000-4000-8000-00000000f020',1,'00000000-0000-4000-8000-00000000f061')$$,'P0001','contract_review_already_requested','new request ID cannot duplicate review of same version');
select throws_ok($$select public.request_project_contract_review('00000000-0000-4000-8000-00000000f020',2,'00000000-0000-4000-8000-00000000f060')$$,'P0001','request_id_payload_mismatch','request cannot target another version');
select public.save_project_contract('00000000-0000-4000-8000-00000000f020',1,'00000000-0000-4000-8000-00000000f041',current_setting('test.contract_data')::jsonb||'{"feeBasis":"New basis"}');
select is(public.read_project_contract('00000000-0000-4000-8000-00000000f020')->'reviewRequests'->0->>'status','superseded','new preparation supersedes old request without mutation');
select is(public.request_project_contract_review('00000000-0000-4000-8000-00000000f020',1,'00000000-0000-4000-8000-00000000f060')->>'submittedVersion','1','old retry reports original target after new save');
select throws_ok($$select public.request_project_contract_review('00000000-0000-4000-8000-00000000f020',1,'00000000-0000-4000-8000-00000000f061')$$,'P0001','contract_version_conflict','new stale request cannot freeze obsolete version');
select is((select c.data->>'feeBasis' from public.project_contract_versions c join public.project_contract_review_requests r on r.contract_version_id=c.id),'Monthly management fee','requested source remains frozen');
select throws_ok($$select public.decide_project_gate01('00000000-0000-4000-8000-00000000f020',0,'00000000-0000-4000-8000-00000000f050',null,'conditional_go','Request is not approval','[]')$$,'P0001','contract_authorized_review_required','review request cannot bypass Conditional Go guard');
reset role;
update public.user_permission_overrides set effect='revoke' where permission_key='project.setup.edit' and workspace_id='00000000-0000-4000-8000-00000000f010';
set local role authenticated;
select throws_ok($$select public.request_project_contract_review('00000000-0000-4000-8000-00000000f020',2,'00000000-0000-4000-8000-00000000f061')$$,'P0001','missing_setup_edit_permission','membership does not grant review intake permission');
select ok(not has_table_privilege('authenticated','public.project_contract_review_requests','INSERT,UPDATE,DELETE'),'client cannot directly mutate requests');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-00000000f002","role":"authenticated"}',true);
select is((select count(*)::integer from public.project_contract_review_requests),0,'outsider cannot read requests');
select throws_ok($$select public.request_project_contract_review('00000000-0000-4000-8000-00000000f020',2,'00000000-0000-4000-8000-00000000f061')$$,'P0001','project_state_not_found_or_access_denied','outsider cannot request review');
reset role;
update public.user_permission_overrides set effect='grant' where permission_key='project.setup.edit' and workspace_id='00000000-0000-4000-8000-00000000f010';
update public.project_states set archived_at=now() where id='00000000-0000-4000-8000-00000000f020';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-00000000f001","role":"authenticated"}',true);
select throws_ok($$select public.request_project_contract_review('00000000-0000-4000-8000-00000000f020',2,'00000000-0000-4000-8000-00000000f061')$$,'P0001','contract_edit_not_allowed','archived projects cannot request review');
select * from finish();
rollback;
